import { useEffect, useRef, useState } from 'react';
export default function Experience() {
  const [n, setN] = useState(0);
  const r = useRef(null);
  useEffect(() => {}, []);
  return (
    <main>
      <h1 ref={r}>Full custom lifecycle</h1>
      <button onClick={() => setN(n + 1)}>Count {n}</button>
    </main>
  );
}
